package io.knowledgebrain.activity;
import java.util.*;
import org.junit.jupiter.api.Test;
import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;
import io.knowledgebrain.contracts.knowledge.claim.v2.ClaimChangedPayloadV2;
import static org.junit.jupiter.api.Assertions.*;
class ClaimActivityTest extends ActivityFixtures {
 static final String TOPIC="knowledge.claim.v2";
 static byte[] change(byte[] raw,String type,String value,long version,boolean retired)throws Exception{var e=RoadmapEventEnvelopeV1.parseFrom(raw);var p=ClaimChangedPayloadV2.parseFrom(e.getPayload()).toBuilder().setRevisionId(id().toString()).setObjectType(type).setObjectConceptId(type.equals("CONCEPT")?value:"").setObjectValue(type.equals("CONCEPT")?"":value).setVersion(version).setState(retired?"RETIRED":"ACTIVE").build();return e.toBuilder().setEventId(id().toString()).setEventType(retired?"ClaimRetired":version==1?"ClaimCreated":"ClaimUpdated").setPayload(p.toByteString()).build().toByteArray();}
 @Test void fiveKindsKeepExactValuesAndImmutableRevisionReferences()throws Exception{var raw=wire("CLAIM",id());for(var pair:Map.of("CONCEPT",id().toString(),"STRING","😀".repeat(1000),"NUMBER","9007199254740993.123456789012345678","DATE","1582-10-10","BOOLEAN","false").entrySet()){var bytes=change(raw,pair.getKey(),pair.getValue(),2,false);var e=ActivityEvent.decode(TOPIC,bytes);assertEquals(pair.getKey(),e.claim().object().type());assertEquals(pair.getValue(),pair.getKey().equals("CONCEPT")?e.claim().object().conceptId().toString():e.claim().object().value());assertTrue(ActivityEvent.target(e));assertEquals("",e.detail());assertNull(e.roadmapId());var json=tools.jackson.databind.json.JsonMapper.builder().build();assertEquals(e,json.readValue(json.writeValueAsString(e),ActivityEvent.class));String object=json.writeValueAsString(e.claim().object());assertFalse(object.contains(":null"));ActivityEvent.transport(TOPIC,bytes,e.aggregateId().toString(),headers(e));}}
 @Test void legacyConceptAndCurrentTypedTopicsUseIndependentVersionAndRegistryBindings()throws Exception{var v2=change(wire("CLAIM",id()),"CONCEPT",id().toString(),1,false);var v1=RoadmapEventEnvelopeV1.parseFrom(v2).toBuilder().setEventVersion(1).build().toByteArray();var old=ActivityEvent.decode("knowledge.claim.v1",v1);var now=ActivityEvent.decode(TOPIC,v2);assertEquals(now,old);var header=new HashMap<>(headers(old));header.put("schema_artifact","claim-events");ActivityEvent.transport("knowledge.claim.v1",v1,old.aggregateId().toString(),header);assertThrows(IllegalArgumentException.class,()->ActivityEvent.transport(TOPIC,v2,now.aggregateId().toString(),header));assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,v1));assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode("knowledge.claim.v1",v2));var scalar=RoadmapEventEnvelopeV1.parseFrom(wire("CLAIM",id())).toBuilder().setEventVersion(1).build().toByteArray();assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode("knowledge.claim.v1",scalar));assertEquals(27,ActivityEvent.topics().size());}
 @Test void invalidShapesCanonicalValuesAndPublicOrUnverifiedEnvelopeFailClosed()throws Exception{var raw=wire("CLAIM",id());for(String[] bad:List.of(new String[]{"NUMBER","1e3"},new String[]{"NUMBER","1.0"},new String[]{"NUMBER","-0"},new String[]{"NUMBER","1.1234567890123456789"},new String[]{"NUMBER","9".repeat(39)},new String[]{"DATE","2025-02-29"},new String[]{"DATE","0000-02-29"},new String[]{"BOOLEAN","False"},new String[]{"ENUM","x"},new String[]{"STRING"," "},new String[]{"STRING","x".repeat(1001)},new String[]{"STRING","a\u0000b"})){assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,change(raw,bad[0],bad[1],1,false)));}var e=RoadmapEventEnvelopeV1.parseFrom(raw);var p=ClaimChangedPayloadV2.parseFrom(e.getPayload());for(var bad:List.of(p.toBuilder().setVisibility("PUBLIC"),p.toBuilder().setVerificationState("EXPERT_VERIFIED"),p.toBuilder().setObjectConceptId(id().toString()),p.toBuilder().setObjectType("CONCEPT"),p.toBuilder().setSubjectConceptId("bad"),p.toBuilder().setRevisionId("bad"),p.toBuilder().setClaimId(id().toString()),p.toBuilder().setVersion(0),p.toBuilder().setVersion(2),p.toBuilder().setState("RETIRED"))){assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,e.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}for(var bad:List.of(e.toBuilder().setProducer("content-service"),e.toBuilder().setEventType("ClaimVerified"),e.toBuilder().setAggregateType("Concept")))assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,bad.build().toByteArray()));}
 @Test void legacyStoredRowsRemainReadableAndClaimCursorIsSpaceAndKindBound(){var json=tools.jackson.databind.json.JsonMapper.builder().build();var note=ActivityEvent.decode(ActivityEvent.TOPICS.get("NOTE"),wire("NOTE",id()));var node=(tools.jackson.databind.node.ObjectNode)json.readTree(json.writeValueAsString(note));node.remove("claim");assertEquals(note,json.treeToValue(node,ActivityEvent.class));var e=ActivityEvent.decode(TOPIC,wire("CLAIM",id()));var q=ActivityQuery.parse(e.spaceId(),ActivityQueryTest.params("kind","CLAIM"));var params=ActivityQueryTest.params("kind","CLAIM","before",q.cursor(e));assertEquals(e.eventId(),ActivityQuery.parse(e.spaceId(),params).event());assertThrows(RuntimeException.class,()->ActivityQuery.parse(id(),params));params.put("kind",new String[]{"NOTE"});assertThrows(RuntimeException.class,()->ActivityQuery.parse(e.spaceId(),params));}
}
